var gulp    = require('gulp'),
    sass    = require('gulp-sass')(require('sass')),
    connect = require('gulp-connect'),
    pug     = require('gulp-pug'),
    plumber = require('gulp-plumber'),
    rename  = require('gulp-rename'),
    uglify  = require('gulp-uglify'),
    clean   = require('gulp-clean'),
    concat  = require('gulp-concat'),
    autoprefixer = require('gulp-autoprefixer');

function reload(done) {
    connect.server({
        root: 'public',
        livereload: true,
        port: 8080
    });
    done();
}

function cleanPublic() {
    return (
        gulp.src('public/*', {read: false})
        .pipe(plumber())
        .pipe(clean())
    );
}

function styles() {
    return (
        gulp.src('src/sass/sassy.sass')
        .pipe(plumber())
        .pipe(sass().on('error', sass.logError))
        .pipe(gulp.dest('.tmp/sass'))
        .pipe(sass())
        .pipe(autoprefixer({
            overrideBrowserslist: ['last 3 versions'],
            cascade: false
        }))
        .pipe(sass({outputStyle: 'expanded'}))
        .pipe(gulp.dest('public/css'))
        .pipe(sass({outputStyle: 'compressed'}))
        .pipe(rename('sassy.min.css'))
        .pipe(gulp.dest('public/css'))
        .pipe(connect.reload())
    );
}

function libs() {
    return (
        gulp.src(['src/js/libs/*.js'])
        .pipe(plumber())
        .pipe(gulp.dest('public/js'))
        .pipe(uglify())
        .pipe(rename((path) => {
            path.extname = ".min.js";
        }))
        .pipe(gulp.dest('public/js'))
        .pipe(connect.reload())
    );
}

function scripts() {
    return (
        gulp.src(['src/js/*.js'])
        .pipe(plumber())
        .pipe(gulp.dest('public/js/tmp'))
        .pipe(uglify())
        .pipe(rename((path) => {
            path.extname = ".min.js";
        }))
        .pipe(gulp.dest('public/js/tmp'))
        .pipe(connect.reload())
    );
}

function allScripts() {
    return (
        gulp.src('src/js/*.js')
        .pipe(plumber())
        .pipe(concat('m.js'))
        .pipe(gulp.dest('public/js'))
        .pipe(uglify())
        .pipe(rename((path) => {
            path.extname = ".min.js";
        }))
        .pipe(gulp.dest('public/js'))
        .pipe(connect.reload())
    );
}

function html() {
    return (
        gulp.src('src/views/html/**/*.html')
        .pipe(plumber())
        .pipe(gulp.dest('public/'))
        .pipe(connect.reload())
    );
}

function views() {
    return (
        gulp.src('src/views/pages/**/*.pug')
        .pipe(plumber())
        .pipe(pug({
            pretty: true
        }))
        .pipe(gulp.dest('public/'))
        .pipe(connect.reload())
    )
}

function assets() {
    return (
        gulp.src(['src/assets/**/**/*'])
        .pipe(plumber())
        .pipe(gulp.dest('public/'))
        .pipe(connect.reload())
    )
}

function watchTask(done) {
    gulp.watch('src/**/**/*.html', html);
    gulp.watch('src/sass/**/**/*.sass', styles);
    gulp.watch('src/js/libs/**/*.js', libs);
    gulp.watch('src/js/**/**/*.js', gulp.series(scripts, allScripts));
    gulp.watch('src/views/**/**/*.pug', views);
    done();
}

const build = gulp.series(cleanPublic, gulp.parallel(assets, styles, libs, scripts, allScripts, views));
const watch = gulp.parallel(build, watchTask, reload);

exports.reload = reload;
exports.clean = cleanPublic;
exports.assets = assets;
exports.styles = styles;
exports.libs = libs;
exports.scripts = scripts;
exports.allScripts = allScripts;
exports.html = html;
exports.views = views;
exports.watch = watch;
exports.build = build;
exports.default = watch;

/**
 * createPie() - Creates a progress pie
 * 
 * @param {String} key - Identifies the progress pie.
 * @param {Number} percent - Defines the progress percentage. Any number from 0 to 100.
 * @returns - The SVG Element
 */
function createPie(key, percent) {

    /****************************
     * Creates SVG Viewbox
     ****************************/
    const box = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    box.id = 'box' + key;
    box.classList.add('pie-box');

    // Sets viewBox attributes
    box.setAttributeNS(null, 'viewBox', '0 0 20 20');
    box.setAttributeNS(null, 'height', '20');
    box.setAttributeNS(null, 'width', '20');


    /****************************
     * Creates SVG Circle
     ****************************/
    const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
    circle.classList.add('pie-circle');

    // Sets circle attributes
    circle.setAttributeNS(null, 'r', '5');
    circle.setAttributeNS(null, 'cx', '10');
    circle.setAttributeNS(null, 'cy', '10');

    // Calculates progress percentage
    circle.setAttributeNS(null, 'stroke-width', '10');
    circle.setAttributeNS(null, 'stroke-dasharray', 'calc('+percent+' * 31.4 / 100) 31.4');
    circle.setAttributeNS(null, 'style', "transform: rotate(-90deg) translate(-20px);");

    // Appends Circle to SVG
    box.append(circle);

    return box;
}

/**
 * updatePie() - Updates the percentage value of a progress pie.
 * 
 * @param {Object} pie - The SVG Element you want to update
 * @param {Number} percent - The progress percentage you want to update. Any number from 0 to 100.
 * @returns - The SVG element
 */
function updatePie(pie, percent) {
    // Gets <circle> element
    const pieCircle = pie.firstChild;

    // Updates attribute
    pieCircle.setAttributeNS(null, 'stroke-dasharray', 'calc('+percent+' * 31.4 / 100) 31.4');

    // Returns the <svg> element
    return pie;
}

/**
 * getPies()
 * 
 * @returns Returns an Array with all the progress pies in the DOM.
 */
function getPies() {
    // Gets all the pies and circles in the DOM
    const pieBoxes = document.querySelectorAll('.pie-box');
    const pieCircles = document.querySelectorAll('.pie-circle');

    // Creates an array of all Pies
    const allPies = [];

    pieBoxes.forEach((box, index) => {
        // Adds the pie (<svg>) and circle (<circle>) to an object
        const pieObject = {
            box,
            circle: pieCircles[index]
        };

        // Pushes pieObject to the allPies array
        allPies.push(pieObject);
    });

    // Returns allPies
    return allPies;
}

